import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Databases → ER model; Relational model and integrity constraints; Relational algebra and tuple calculus; SQL.
 * Numbers from lib/study/db.ts, checked by script: ER tables 1:1 → 2, 1:N → 2, M:N → 3, 1:1 both total → 1, M:N + 1 multivalued + 1 weak → 5.
 * R(ABCDE), A→B, BC→D, D→E, E→A: keys AC, BC, CD, CE; 15 superkeys; all attributes prime. R(ABCD), AB→C, C→D, D→A: keys AB, BC, BD.
 * Sample data: σ dept='CS' → 2 rows; π name → 4; who takes DB → Asha, Chen, Dev; Student × Course → 12 rows; no OS course → sids 2, 4;
 * Enrolled ÷ CS courses → sids 1, 3. Emp: COUNT(*) 5, COUNT(salary) 4, AVG(salary) 55; GROUP BY HAVING COUNT ≥ 2 → CS 120, EC 60;
 * above average → Ira, Kim; > ALL EC → Ira; > ANY CS → Ira, Kim; NOT IN with a NULL → 0 rows; LEFT JOIN Course–Enrolled → 6 rows.
 */
