const keys: Topic = {
  id: "cs.db.rel.keys",
  title: "Relations, keys and superkeys",
  blocks: [
    { type: "hook", text: "A table can have many ways to identify a row, yet only some are minimal. Finding all candidate keys from a set of dependencies, and counting superkeys, appears in GATE nearly every year." },
    { type: "objectives", items: ["Define superkeys, candidate keys, primary and foreign keys.", "Compute attribute closures and find all candidate keys.", "Count superkeys."] },
    { type: "intuition", paras: ["A relation is a set of tuples over named attributes; no two tuples are identical. A superkey is any set of attributes that determines all the others. A candidate key is a superkey with nothing removable.", "The closure X⁺ is every attribute determined by X under the functional dependencies. X is a superkey exactly when X⁺ contains every attribute.", "Attributes that never appear on any right side must be in every key; attributes only on the right side are never in a key. That narrows the search a lot."], analogyLimit: "Like the fewest facts that identify a person: name plus date of birth may work, but adding the city changes nothing." },
    { type: "definition", name: "Keys", text: "For relation R and dependencies F:", items: ["Superkey: X with X⁺ = R. Candidate key: minimal superkey. Primary key: the chosen candidate key.", "Prime attribute: belongs to some candidate key.", "Foreign key: attributes referencing another relation's primary key.", "Attributes appearing in no right side belong to every candidate key."] },
    { type: "deep", sections: [
      { h: "Computing a closure", paras: ["Start with X. Repeat: for each dependency Y → Z with Y inside the current set, add Z. Stop when nothing changes. For A→B, BC→D, D→E, E→A: {A, C}⁺ = {A, B, C, D, E}, so AC is a superkey; neither A⁺ = {A, B} nor C⁺ = {C} is, so AC is a candidate key."] },
      { h: "Counting superkeys", paras: ["Every superset of a candidate key is a superkey. With a single candidate key of k attributes in an n-attribute relation, there are 2^(n−k) superkeys. With several keys, use inclusion–exclusion over their supersets."] },
      { h: "Trick for finding keys", points: ["Core: attributes on no right side must be in every key.", "Never: attributes on right sides only are in no key.", "Try the core; if its closure is not everything, add the remaining 'middle' attributes one at a time."], paras: [] },
      { h: "Relation properties", paras: ["Rows are unordered and distinct; values are atomic (first normal form). Two relations are union-compatible when they have the same number of attributes with matching domains."] },
    ] },
    { type: "walkthrough", steps: ["Find attributes on no right side (they are in every key).", "Compute the closure of that core.", "If it is not all of R, add one other attribute at a time and test.", "Keep only minimal sets; list superkeys as their supersets."], prompt: { q: "With one candidate key A in R(A, B, C, D), how many superkeys?", a: "2³ = 8: A with any subset of B, C, D." } },
    { type: "figure", id: "keys-ring", caption: "R(A, B, C, D, E) with A → B, BC → D, D → E, E → A.", alt: "C is in every key; the keys are AC, BC, CD, CE.", fig: { kind: "matrix", title: "Closures", cols: ["Closure", "Key?"], rows: [{ label: "C", cells: ["{C}", "no"] }, { label: "AC", cells: ["{A,B,C,D,E}", "yes"], hl: true }, { label: "BC", cells: ["{A,B,C,D,E}", "yes"] }, { label: "CD", cells: ["{A,B,C,D,E}", "yes"] }, { label: "CE", cells: ["{A,B,C,D,E}", "yes"] }] } },
    { type: "example", id: "kx1", level: "gate", title: "All candidate keys", given: "R(A, B, C, D, E), F = {A → B, BC → D, D → E, E → A}.", find: "All candidate keys.",
      steps: [
        { say: "C is on no right side: it is in every key. C⁺ = {C}." },
        { say: "Try C with one more: AC, BC, CD, CE all reach everything (e.g. CE: E→A, A→B, BC→D)." },
        { say: "No single attribute works.", result: "AC, BC, CD, CE" },
      ],
      answer: "Four candidate keys: AC, BC, CD, CE. Every attribute is prime.",
      check: "15 superkeys in all (the lab counts them)." },
    { type: "figure", id: "superkeys", for: "kx2", caption: "Superkeys from one candidate key.", alt: "A key of 1 attribute in 4 attributes gives 8 superkeys.", fig: { kind: "strip", items: [{ label: "Key A", sub: "must be present", state: "done" }, { label: "B, C, D", sub: "each in or out", state: "done" }, { label: "Superkeys", sub: "2³ = 8", state: "now" }] } },
    { type: "example", id: "kx2", level: "gate", title: "Counting superkeys", given: "R(A, B, C, D) with candidate keys A and B only.", find: "The number of superkeys.",
      steps: [
        { say: "Supersets of A: 2³ = 8. Supersets of B: 8. Supersets of both AB: 2² = 4." },
        { say: "8 + 8 − 4.", result: "12" },
      ],
      answer: "12 superkeys.",
      check: "Inclusion–exclusion avoids double-counting sets containing both A and B." },
    { type: "example", id: "kx3", level: "edge", title: "Every attribute prime", given: "R(A, B, C, D), F = {AB → C, C → D, D → A}.", find: "Candidate keys.",
      steps: [
        { say: "B is on no right side: in every key. B⁺ = {B}." },
        { say: "AB⁺ = all; BC⁺: C→D→A, so all; BD⁺: D→A, AB→C, so all.", result: "AB, BC, BD" },
      ],
      answer: "AB, BC, BD; every attribute is prime.",
      check: "This relation is in 3NF but not BCNF (C → D with C not a superkey)." },
    { type: "lab", lab: "keys" },
    { type: "faded", title: "Your turn", given: "R(A, B, C, D), F = {A → B, B → C, C → D}.",
      steps: [{ say: "Candidate keys and number of superkeys?", blank: true, answer: "A only; 2³ = 8 superkeys." }] },
    { type: "trap", wrong: "A candidate key is the smallest superkey by size.", tempting: "Minimal sounds like smallest.", whyWrong: "Minimal means no attribute can be removed; keys of different sizes can all be candidate keys.", rule: "Minimal by subset, not by count." },
    { type: "trap", wrong: "Counting superkeys as the sum of supersets of each key.", tempting: "Each key gives 2^(n−k).", whyWrong: "Sets containing two keys are counted twice.", rule: "Inclusion–exclusion." },
    { type: "gate", text: "GATE gives a relation and dependencies and asks the candidate keys, the number of candidate keys or superkeys, or prime attributes. Start from attributes on no right side." },
    { type: "recall", cards: [{ q: "Superkey test", a: "X⁺ = all attributes" }, { q: "Always in every key", a: "Attributes on no right side" }, { q: "Superkeys from one k-key in n attributes", a: "2^(n−k)" }] },
    { type: "check", questions: [
      { id: "ky1", kind: "NAT", marks: 2, q: "R(ABCDE), A→B, BC→D, D→E, E→A. Number of candidate keys?", answer: "4", solution: "AC, BC, CD, CE." },
      { id: "ky2", kind: "NAT", marks: 2, q: "R(A, B, C, D) with candidate keys A and B only. Number of superkeys?", answer: "12", solution: "8 + 8 − 4." },
      { id: "ky3", kind: "NAT", marks: 1, q: "R(A, B, C, D), A→B, B→C, C→D. Number of superkeys?", answer: "8", solution: "2³." },
      { id: "ky4", kind: "MCQ", marks: 1, q: "For R(ABCD), AB→C, C→D, D→A, which is not a candidate key?", options: ["AB", "BC", "BD", "CD"], answer: "D", solution: "B is missing." },
      { id: "ky5", kind: "MSQ", marks: 2, q: "Which are true?", options: ["Every candidate key is a superkey", "Every superkey is a candidate key", "A relation can have several candidate keys", "A prime attribute belongs to some candidate key"], answer: "A, C, D", solution: "Superkeys need not be minimal." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "Keys", href: DB }, { label: "Functional dependencies", sub: "Closures and covers", href: "/study/normal-forms" }, { label: "Topic 2: integrity constraints", sub: "Foreign keys", href: "/study/relational-model" }] },
    { type: "links", prereq: ["Sets"], usedIn: ["Normalisation"], cross: ["Discrete Mathematics: relations"] },
  ],
};

const integrity: Topic = {
  id: "cs.db.rel.integrity",
  title: "Integrity constraints and referential actions",
  blocks: [
    { type: "hook", text: "Delete a department and twelve employees suddenly point at nothing. Integrity constraints decide whether the database refuses, follows along, or blanks the reference." },
    { type: "objectives", items: ["Distinguish domain, key, entity and referential integrity.", "Predict the effect of ON DELETE / ON UPDATE actions.", "Decide which insertions and deletions are allowed."] },
    { type: "intuition", paras: ["Domain constraints limit values (age is an integer, 0 to 150). Key constraints forbid duplicate key values. Entity integrity forbids NULL in a primary key.", "Referential integrity says a foreign key value must match an existing primary key in the referenced table, or be NULL.", "When a referenced row is deleted or its key changes, the foreign key's action decides: RESTRICT/NO ACTION (refuse), CASCADE (delete or update the referencing rows too), SET NULL or SET DEFAULT."], analogyLimit: "Like a library card pointing at a book; removing the book needs a rule for the cards." },
    { type: "definition", name: "Constraints", text: "Kinds of integrity:", items: ["Domain: values from the attribute's type and range; CHECK constraints.", "Key: primary key and UNIQUE values are distinct. Entity integrity: primary key never NULL.", "Referential: each foreign key value is NULL or matches a referenced key.", "Actions: RESTRICT / NO ACTION, CASCADE, SET NULL, SET DEFAULT on DELETE and UPDATE."] },
    { type: "deep", sections: [
      { h: "Which operations can violate what", points: ["Insert into the referencing table: may violate referential integrity (no matching parent).", "Delete from the referenced table: may violate it (orphans); actions apply here.", "Update a referenced key: same as delete plus insert; ON UPDATE actions apply.", "Insert into or delete from the referencing table never breaks the parent."], paras: [] },
      { h: "Cascade chains", paras: ["If A is referenced by B with ON DELETE CASCADE and B by C with CASCADE, deleting one A row may delete rows in B and then in C. GATE questions ask how many rows disappear in total."] },
      { h: "Self-referencing keys", paras: ["Employee(id, manager_id) where manager_id references id. Deleting a manager with CASCADE deletes the whole reporting subtree; with SET NULL the reports keep their rows but lose the manager."] },
      { h: "Assertions and triggers", paras: ["Constraints that span many rows (total participation, 'at most 50 students per course') need CHECK with subqueries (rarely supported), assertions, or triggers."] },
    ] },
    { type: "walkthrough", steps: ["Identify parent (referenced) and child (referencing) tables.", "For an insert into the child: does the parent row exist?", "For a delete or key update in the parent: apply the declared action to matching child rows.", "Follow cascades through further tables."], prompt: { q: "Can a foreign key column be NULL?", a: "Yes, unless declared NOT NULL; a NULL foreign key references nothing and does not violate referential integrity." } },
    { type: "figure", id: "fk-actions", caption: "Deleting department CS with two employees in it.", alt: "Restrict refuses, cascade deletes employees, set null clears their dept.", fig: { kind: "matrix", title: "ON DELETE", cols: ["Dept CS", "Employees 1, 2"], rows: [{ label: "RESTRICT", cells: ["kept", "kept (delete refused)"] }, { label: "CASCADE", cells: ["deleted", "deleted"], hl: true }, { label: "SET NULL", cells: ["deleted", "dept = NULL"] }] } },
    { type: "example", id: "ix1", level: "gate", title: "Referential actions", given: "Emp(id, dept) references Dept(dept). Employees 1, 2 in CS, 3 in EC. Delete CS.", find: "Result under RESTRICT, CASCADE and SET NULL.",
      steps: [
        { say: "RESTRICT: employees reference CS, so the delete is refused." },
        { say: "CASCADE: CS and employees 1, 2 are deleted; 3 stays." },
        { say: "SET NULL: CS deleted; employees 1, 2 keep their rows with dept NULL.", result: "three outcomes" },
      ],
      answer: "Refused; 3 rows deleted (1 dept + 2 emp); 1 row deleted and 2 updated.",
      check: "Deleting ME (no employees) succeeds under all three." },
    { type: "figure", id: "fk-chain", for: "ix2", caption: "A cascade chain.", alt: "Deleting one customer deletes their orders and those orders' items.", fig: { kind: "strip", items: [{ label: "Customer 7", sub: "deleted", state: "bad" }, { label: "3 orders", sub: "CASCADE", state: "bad" }, { label: "8 order items", sub: "CASCADE", state: "bad" }] } },
    { type: "example", id: "ix2", level: "gate", title: "Counting cascaded deletions", given: "Customer → Order → OrderItem, both foreign keys ON DELETE CASCADE. Customer 7 has 3 orders with 2, 2 and 4 items.", find: "Rows deleted when customer 7 is deleted.",
      steps: [
        { say: "1 customer + 3 orders + (2 + 2 + 4) items." },
        { say: "Total.", result: "12" },
      ],
      answer: "12 rows.",
      check: "With RESTRICT on Order → Customer, nothing would be deleted." },
    { type: "example", id: "ix3", level: "edge", title: "Which inserts fail?", given: "Dept has CS and EC. Emp.dept references Dept, nullable.", find: "Which inserts are accepted: (4, 'ME'), (5, NULL), (6, 'EC')?",
      steps: [
        { say: "'ME' has no parent row: rejected." },
        { say: "NULL references nothing: accepted. 'EC' exists: accepted.", result: "2 accepted" },
      ],
      answer: "(5, NULL) and (6, 'EC') are accepted; (4, 'ME') is rejected.",
      check: "Declaring dept NOT NULL would also reject (5, NULL)." },
    { type: "lab", lab: "fk" },
    { type: "faded", title: "Your turn", given: "Employee(id, manager_id → Employee.id) ON DELETE CASCADE. A manages B and C; B manages D.",
      steps: [{ say: "Delete A: how many rows go?", blank: true, answer: "A, B, C, then D (via B): 4." }] },
    { type: "trap", wrong: "Deleting from the referencing table can break referential integrity.", tempting: "Any delete seems risky.", whyWrong: "Removing a child row leaves no dangling reference; only parent deletes or child inserts can.", rule: "Watch parent deletes and child inserts." },
    { type: "trap", wrong: "A NULL foreign key violates referential integrity.", tempting: "It matches no parent.", whyWrong: "NULL means 'no reference'; it is allowed unless NOT NULL is declared.", rule: "FK must match a parent or be NULL." },
    { type: "gate", text: "GATE asks rows deleted under CASCADE chains, which operations violate which constraints, and outcomes of referential actions." },
    { type: "recall", cards: [{ q: "Entity integrity", a: "No NULL in a primary key" }, { q: "ON DELETE CASCADE", a: "Delete matching child rows too" }, { q: "Child insert with no parent", a: "Rejected" }] },
    { type: "check", questions: [
      { id: "ic1", kind: "NAT", marks: 2, q: "Customer → Order → Item, both CASCADE. A customer has 3 orders with 2, 2, 4 items. Rows deleted when the customer is deleted?", answer: "12", solution: "1 + 3 + 8." },
      { id: "ic2", kind: "MCQ", marks: 1, q: "Which can violate referential integrity?", options: ["Deleting a child row", "Inserting a parent row", "Inserting a child row with a missing parent", "Updating a non-key parent column"], answer: "C", solution: "No matching parent." },
      { id: "ic3", kind: "NAT", marks: 1, q: "Self-referencing manager key with CASCADE: A manages B and C, B manages D. Rows deleted when A is deleted?", answer: "4", solution: "A, B, C, D." },
      { id: "ic4", kind: "MSQ", marks: 2, q: "Which are true?", options: ["A primary key cannot be NULL", "A foreign key can be NULL unless NOT NULL is declared", "RESTRICT deletes the children", "SET NULL keeps the child rows"], answer: "A, B, D", solution: "RESTRICT refuses the delete." },
      { id: "ic5", kind: "MCQ", marks: 1, q: "Deleting a department with employees under ON DELETE RESTRICT", options: ["Deletes all", "Is refused", "Sets dept to NULL", "Deletes only the department"], answer: "B", solution: "Children still reference it." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "Constraints", href: DB }, { label: "Topic 1: keys", sub: "Primary and foreign keys", href: "/study/relational-model" }, { label: "SQL", sub: "CREATE TABLE constraints", href: "/study/sql" }] },
    { type: "links", prereq: ["Keys"], usedIn: ["Schema design", "SQL DDL"], cross: ["SQL"] },
  ],
};

const algebra: Topic = {
  id: "cs.db.ra.algebra",
  title: "Relational algebra",
  blocks: [
    { type: "hook", text: "Every SQL query runs as a tree of six or seven simple operations underneath. Relational algebra is that tree, and GATE asks what it returns, how many rows, and which expressions are equivalent." },
    { type: "objectives", items: ["Use selection, projection, union, difference, product, join and division.", "Count result rows for products and joins.", "Write 'for all' queries with division."] },
    { type: "intuition", paras: ["Selection σ keeps rows meeting a condition; projection π keeps columns and removes duplicates. Union, difference and intersection need union-compatible relations.", "The Cartesian product × pairs every row with every row: |R|·|S| rows. A natural join ⋈ keeps pairs that agree on the common attributes, merging those columns.", "Division R ÷ S answers 'who is related to every S': the values in R paired with all rows of S. It is how algebra says 'for all'."], analogyLimit: "Like a set of kitchen tools that can be chained in any order; but projection silently removes duplicates, unlike SQL's SELECT." },
    { type: "definition", name: "Operators", text: "On relations R and S:", items: ["σ_p(R): rows satisfying p. π_A(R): columns A, duplicates removed.", "R ∪ S, R − S, R ∩ S (= R − (R − S)): union-compatible only.", "R × S: |R|·|S| rows; R ⋈ S: join on equal common attributes; θ-join: σ_θ(R × S).", "R ÷ S: tuples t (on R's other attributes) with (t, s) ∈ R for every s ∈ S.", "Basic set: σ, π, ∪, −, ×, ρ (rename); the rest are derived."] },
    { type: "deep", sections: [
      { h: "Row counts", points: ["R × S: exactly |R|·|S|.", "Natural join: between 0 and |R|·|S|; with a foreign key from R to S's key, exactly |R| (each R row matches one S row).", "π can shrink the count (duplicates removed); σ never increases it.", "R ∪ S: between max(|R|, |S|) and |R| + |S|."], paras: [] },
      { h: "Division by algebra", paras: ["R(x, y) ÷ S(y) = π_x(R) − π_x((π_x(R) × S) − R). The inner part finds (x, y) pairs that should exist but do not; removing their x values leaves those related to every y."] },
      { h: "Equivalences used by optimisers", paras: ["Push selections down: σ_p(R ⋈ S) = σ_p(R) ⋈ S if p uses only R's attributes. Cascade projections. Joins are commutative and associative. These rewrites make queries cheaper without changing results."] },
      { h: "Outer joins", paras: ["Left outer join keeps every left row, padding missing right values with NULL. Full outer join keeps unmatched rows from both sides. They are not expressible with the basic operators because algebra has no NULL."] },
    ] },
    { type: "walkthrough", steps: ["Evaluate inside out: innermost relation first.", "Apply σ (filter rows), then ⋈ or ×, then π (columns, deduplicate).", "Count rows at each step.", "For 'every', reach for division."], prompt: { q: "How many rows does Student × Course have with 4 students and 3 courses?", a: "12." } },
    { type: "figure", id: "ra-data", caption: "Sample data used in this topic and the lab.", alt: "Enrolled pairs: Asha DB OS, Bala VLSI, Chen DB OS, Dev DB.", fig: { kind: "matrix", title: "Enrolled", cols: ["DB", "OS", "VLSI"], rows: [{ label: "1 Asha (CS)", cells: ["✓", "✓", ""] }, { label: "2 Bala (EC)", cells: ["", "", "✓"] }, { label: "3 Chen (CS)", cells: ["✓", "✓", ""], hl: true }, { label: "4 Dev (ME)", cells: ["✓", "", ""] }] } },
    { type: "example", id: "rx1", level: "gate", title: "Join, select, project", given: "The sample data.", find: "π name(σ cid='DB'(Student ⋈ Enrolled)).",
      steps: [
        { say: "Student ⋈ Enrolled: 6 rows (one per enrolment)." },
        { say: "Keep cid = 'DB': sids 1, 3, 4. Project name.", result: "Asha, Chen, Dev" },
      ],
      answer: "{Asha, Chen, Dev}.",
      check: "Pushing σ into Enrolled first gives the same answer with less work." },
    { type: "figure", id: "ra-div", for: "rx2", caption: "Division: who takes every CS course (DB and OS)?", alt: "Asha and Chen take both.", fig: { kind: "strip", items: [{ label: "CS courses", sub: "{DB, OS}", state: "done" }, { label: "Asha", sub: "DB, OS ✓", state: "now" }, { label: "Chen", sub: "DB, OS ✓", state: "now" }, { label: "Dev", sub: "DB only ✗", state: "bad" }] } },
    { type: "example", id: "rx2", level: "gate", title: "Division", given: "Enrolled(sid, cid) and the CS courses {DB, OS}.", find: "Enrolled ÷ π cid(σ dept='CS'(Course)).",
      steps: [
        { say: "Need sids enrolled in both DB and OS." },
        { say: "Asha (1) and Chen (3) qualify; Dev lacks OS, Bala takes neither.", result: "{1, 3}" },
      ],
      answer: "sids 1 and 3.",
      check: "The lab computes the same 2 rows." },
    { type: "example", id: "rx3", level: "edge", title: "Difference for 'not'", given: "The sample data.", find: "Students taking no OS course.",
      steps: [
        { say: "π sid(Student) = {1, 2, 3, 4}; π sid(σ cid='OS'(Enrolled)) = {1, 3}." },
        { say: "Difference.", result: "{2, 4}" },
      ],
      answer: "sids 2 and 4 (Bala and Dev).",
      check: "σ cid ≠ 'OS'(Enrolled) would wrongly include Asha (she also takes DB)." },
    { type: "lab", lab: "ra" },
    { type: "faded", title: "Your turn", given: "R has 5 rows, S has 4 rows.",
      steps: [{ say: "Rows in R × S, and the range for R ⋈ S?", blank: true, answer: "20; anywhere from 0 to 20." }] },
    { type: "trap", wrong: "'Not taking OS' = σ cid ≠ 'OS'(Enrolled).", tempting: "Negate the condition.", whyWrong: "That keeps every enrolment in another course, including students who also take OS. Use difference.", rule: "'Not any' needs set difference." },
    { type: "trap", wrong: "π keeps duplicates like SELECT.", tempting: "SQL habit.", whyWrong: "Relational algebra works on sets: projection removes duplicates.", rule: "π = SELECT DISTINCT." },
    { type: "gate", text: "GATE asks the output or row count of algebra expressions, equivalent expressions, and division queries ('students who took all courses'). Evaluate inside out and count at each step." },
    { type: "recall", cards: [{ q: "|R × S|", a: "|R|·|S|" }, { q: "'For all' in algebra", a: "Division" }, { q: "Basic operators", a: "σ, π, ∪, −, ×, ρ" }] },
    { type: "check", questions: [
      { id: "ra1", kind: "NAT", marks: 1, q: "Student (4 rows) × Course (3 rows): number of rows?", answer: "12", solution: "4 × 3." },
      { id: "ra2", kind: "NAT", marks: 2, q: "Sample data: how many rows does Enrolled ÷ (CS courses) return?", answer: "2", solution: "sids 1 and 3." },
      { id: "ra3", kind: "NAT", marks: 1, q: "Sample data: rows in π name(σ cid='DB'(Student ⋈ Enrolled))?", answer: "3", solution: "Asha, Chen, Dev." },
      { id: "ra4", kind: "MSQ", marks: 2, q: "Which are derived (not basic) operators?", options: ["Natural join", "Intersection", "Division", "Selection"], answer: "A, B, C", solution: "Selection is basic." },
      { id: "ra5", kind: "MCQ", marks: 2, q: "R(x, y) ÷ S(y) equals", options: ["π_x(R) − π_x((π_x(R) × S) − R)", "π_x(R × S)", "π_x(R) ∩ S", "π_x(R − S)"], answer: "A", solution: "Remove x values missing some y." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "Relational algebra", href: DB }, { label: "Topic 2: tuple calculus", sub: "The same queries as formulas", href: "/study/relational-algebra" }, { label: "SQL", sub: "Algebra in practice", href: "/study/sql" }] },
    { type: "links", prereq: ["Sets"], usedIn: ["SQL", "Query optimisation"], cross: ["Discrete Mathematics: sets"] },
  ],
};

const calculus: Topic = {
  id: "cs.db.ra.calculus",
  title: "Tuple relational calculus and safety",
  blocks: [
    { type: "hook", text: "Relational algebra says how to compute an answer; relational calculus says what the answer is. GATE often gives a calculus formula and asks what it means, or whether it is safe." },
    { type: "objectives", items: ["Read and write tuple relational calculus queries.", "Translate between calculus and algebra.", "Recognise unsafe expressions."] },
    { type: "intuition", paras: ["A TRC query has the form { t | P(t) }: all tuples t for which the formula P is true. Formulas use ∈, comparisons, ∧, ∨, ¬, → and quantifiers ∃ and ∀ over tuples.", "'Exists' corresponds to joins and projections; 'for all' corresponds to division; ¬ with ∃ corresponds to difference.", "A safe query only ever returns values that appear in the database. { t | ¬(t ∈ Student) } is unsafe: it describes infinitely many tuples."], analogyLimit: "Like describing a guest list by its rule ('everyone who took DB') instead of the steps to compile it." },
    { type: "definition", name: "Tuple calculus", text: "A query { t | P(t) } returns all tuples t satisfying P.", items: ["Atoms: t ∈ R, t.A θ s.B, t.A θ constant.", "∃s (s ∈ R ∧ …) ↔ join/projection; ∀s (s ∈ R → …) ↔ division.", "Safe: the result uses only values from the database (domain of the formula).", "Safe TRC, safe domain calculus and relational algebra are equally expressive (Codd's theorem)."] },
    { type: "deep", sections: [
      { h: "Reading quantifiers", paras: ["{ t.name | t ∈ Student ∧ ∃e (e ∈ Enrolled ∧ e.sid = t.sid ∧ e.cid = 'DB') }: names of students with some enrolment in DB. Replacing ∃ with ¬∃ gives students with no DB enrolment."] },
      { h: "Universal queries", paras: ["'Students who take every CS course': { s.sid | s ∈ Student ∧ ∀c (c ∈ Course ∧ c.dept = 'CS' → ∃e (e ∈ Enrolled ∧ e.sid = s.sid ∧ e.cid = c.cid)) }. The → is essential: with ∧ it would require every course to be a CS course."] },
      { h: "Domain relational calculus", paras: ["Variables range over attribute values instead of tuples: { ⟨n⟩ | ∃s ∃d (⟨s, n, d⟩ ∈ Student ∧ d = 'CS') }. QBE (query by example) is based on it."] },
      { h: "Why safety matters", paras: ["A database is finite, but formulas with unrestricted negation describe infinite sets. Requiring every free variable to be bound to a relation (t ∈ R) keeps results finite and computable."] },
    ] },
    { type: "walkthrough", steps: ["Read the free tuple variable: that is what is returned.", "Translate each ∃ into a join with the relation it ranges over.", "Translate ∀…→ into division, ¬∃ into difference.", "Check safety: is every result value drawn from a relation?"], prompt: { q: "Is { t | t ∈ Student ∧ ¬(t ∈ Alumni) } safe?", a: "Yes: t is bound to Student, so the result is a subset of Student." } },
    { type: "figure", id: "trc-map", caption: "Calculus constructs and their algebra counterparts.", alt: "Exists to join, forall to division, not exists to difference.", fig: { kind: "matrix", title: "Translation", cols: ["Algebra"], rows: [{ label: "∃s (s ∈ S ∧ match)", cells: ["⋈ then π"] }, { label: "¬∃s (…)", cells: ["−"] }, { label: "∀s (s ∈ S → …)", cells: ["÷"], hl: true }] } },
    { type: "example", id: "cx1", level: "gate", title: "Reading a query", given: "{ t.name | t ∈ Student ∧ ∃e (e ∈ Enrolled ∧ e.sid = t.sid ∧ e.cid = 'DB') } on the sample data.", find: "The result.",
      steps: [
        { say: "Students with at least one DB enrolment: sids 1, 3, 4." },
        { say: "Their names.", result: "Asha, Chen, Dev" },
      ],
      answer: "{Asha, Chen, Dev}, the same as π name(σ cid='DB'(Student ⋈ Enrolled)).",
      check: "The lab shows both side by side." },
    { type: "figure", id: "trc-all", for: "cx2", caption: "'Every CS course' needs → under ∀.", alt: "Forall c (c is a CS course implies enrolled).", fig: { kind: "strip", items: [{ label: "∀c", sub: "every course", state: "done" }, { label: "c.dept = 'CS' →", sub: "only CS ones matter", state: "now" }, { label: "∃e enrolled", sub: "student takes it", state: "done" }] } },
    { type: "example", id: "cx2", level: "gate", title: "A universal query", given: "{ s.sid | s ∈ Student ∧ ∀c (c ∈ Course ∧ c.dept = 'CS' → ∃e (e ∈ Enrolled ∧ e.sid = s.sid ∧ e.cid = c.cid)) }.", find: "The result on the sample data.",
      steps: [
        { say: "CS courses: DB and OS." },
        { say: "Students enrolled in both: 1 and 3.", result: "{1, 3}" },
      ],
      answer: "sids 1 and 3: the division query.",
      check: "Bala satisfies the → vacuously only for non-CS courses; he fails for DB." },
    { type: "example", id: "cx3", level: "edge", title: "Safety", given: "(a) { t | ¬(t ∈ Student) }, (b) { t | t ∈ Student ∧ t.dept ≠ 'CS' }.", find: "Which are safe?",
      steps: [
        { say: "(a) Every tuple not in Student: infinitely many.", result: "unsafe" },
        { say: "(b) Restricted to Student rows.", result: "safe" },
      ],
      answer: "(a) unsafe, (b) safe.",
      check: "Algebra cannot express (a): it has no 'complement of everything' operator." },
    { type: "lab", lab: "trc" },
    { type: "faded", title: "Your turn", given: "Students who take no course.",
      steps: [{ say: "Write it in TRC.", blank: true, answer: "{ s | s ∈ Student ∧ ¬∃e (e ∈ Enrolled ∧ e.sid = s.sid) }." }] },
    { type: "trap", wrong: "∀c (c ∈ Course ∧ c.dept = 'CS' ∧ enrolled).", tempting: "Join conditions with ∧.", whyWrong: "That claims every course is a CS course; the condition must be the hypothesis of →.", rule: "∀ with →." },
    { type: "trap", wrong: "TRC is more powerful than algebra.", tempting: "It has quantifiers and negation.", whyWrong: "Safe TRC and relational algebra express exactly the same queries.", rule: "Codd's theorem: equal power." },
    { type: "gate", text: "GATE gives a TRC or DRC formula and asks its meaning or its algebra equivalent, and asks which expressions are safe." },
    { type: "recall", cards: [{ q: "∀ in calculus ↔", a: "Division in algebra" }, { q: "Unsafe query", a: "Result not limited to database values" }, { q: "Codd's theorem", a: "Safe calculus = algebra" }] },
    { type: "check", questions: [
      { id: "tc1", kind: "MCQ", marks: 2, q: "{ s.sid | s ∈ Student ∧ ∀c (c ∈ Course ∧ c.dept='CS' → ∃e (e ∈ Enrolled ∧ e.sid=s.sid ∧ e.cid=c.cid)) } corresponds to", options: ["Natural join", "Division", "Union", "Difference only"], answer: "B", solution: "'Every' = division." },
      { id: "tc2", kind: "MCQ", marks: 1, q: "Which is unsafe?", options: ["{ t | t ∈ R }", "{ t | ¬(t ∈ R) }", "{ t | t ∈ R ∧ t.A > 5 }", "{ t | t ∈ R ∧ ¬(t ∈ S) }"], answer: "B", solution: "Unbounded negation." },
      { id: "tc3", kind: "NAT", marks: 2, q: "Sample data: rows returned by the 'every CS course' query?", answer: "2", solution: "sids 1, 3." },
      { id: "tc4", kind: "MSQ", marks: 2, q: "Which are true?", options: ["Safe TRC equals relational algebra in power", "∃ corresponds to joins and projection", "TRC can express outer joins directly", "DRC variables range over attribute values"], answer: "A, B, D", solution: "No NULLs in calculus." },
      { id: "tc5", kind: "NAT", marks: 1, q: "Sample data: rows returned by { t.name | t ∈ Student ∧ ∃e (e ∈ Enrolled ∧ e.sid = t.sid ∧ e.cid = 'DB') }?", answer: "3", solution: "Asha, Chen, Dev." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "Relational calculus", href: DB }, { label: "Topic 1: algebra", sub: "Division", href: "/study/relational-algebra" }, { label: "Discrete Mathematics", sub: "Quantifiers", href: "/study/first-order-logic" }] },
    { type: "links", prereq: ["Relational algebra", "First-order logic"], usedIn: ["SQL semantics"], cross: ["Discrete Mathematics: first-order logic"] },
  ],
};

const sqlBasics: Topic = {
  id: "cs.db.sql.basics",
  title: "SQL queries, aggregation and NULLs",
  blocks: [
    { type: "hook", text: "AVG(salary) over five employees, one with no salary, is not the total divided by five. NULL quietly changes counts, averages and comparisons, and GATE's SQL questions are mostly about exactly that." },
    { type: "objectives", items: ["Write SELECT queries with WHERE, GROUP BY, HAVING and ORDER BY.", "Predict aggregate results with NULLs.", "Use three-valued logic correctly."] },
    { type: "intuition", paras: ["SQL evaluates FROM (and joins) first, then WHERE on rows, then GROUP BY into groups, then HAVING on groups, then SELECT, then ORDER BY. Knowing this order explains most errors.", "Aggregates (COUNT, SUM, AVG, MIN, MAX) ignore NULLs, except COUNT(*), which counts rows.", "Any comparison with NULL is UNKNOWN, not true or false. WHERE keeps only rows where the condition is TRUE, so 'salary = NULL' never matches; use IS NULL."], analogyLimit: "Like counting answers on forms where some boxes are blank; blanks are not zeros, they are simply not counted." },
    { type: "definition", name: "SQL essentials", text: "Logical order of a SELECT:", items: ["FROM → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY.", "COUNT(*) counts rows; COUNT(col), SUM, AVG, MIN, MAX skip NULLs; AVG = SUM/COUNT(col).", "Comparisons with NULL give UNKNOWN; NOT UNKNOWN = UNKNOWN; TRUE AND UNKNOWN = UNKNOWN; TRUE OR UNKNOWN = TRUE.", "SQL returns duplicates unless DISTINCT is used (bags, not sets)."] },
    { type: "deep", sections: [
      { h: "GROUP BY rules", paras: ["Every column in SELECT must be grouped or inside an aggregate. NULLs in a grouping column form one group of their own. HAVING filters groups using aggregates; WHERE cannot use aggregates because it runs before grouping."] },
      { h: "Joins in SQL", points: ["INNER JOIN keeps matching pairs; NATURAL JOIN matches equal-named columns.", "LEFT/RIGHT/FULL OUTER JOIN keep unmatched rows with NULLs.", "A comma in FROM is a Cartesian product; the WHERE clause then filters it."], paras: [] },
      { h: "Three-valued logic table", paras: ["AND: FALSE dominates (FALSE AND UNKNOWN = FALSE). OR: TRUE dominates (TRUE OR UNKNOWN = TRUE). Everything else involving UNKNOWN stays UNKNOWN. A CHECK constraint accepts UNKNOWN, but WHERE rejects it."] },
      { h: "Set operations", paras: ["UNION, INTERSECT, EXCEPT remove duplicates; UNION ALL keeps them. They need the same number of columns with compatible types."] },
    ] },
    { type: "walkthrough", steps: ["Start from FROM and joins: which rows exist?", "Apply WHERE (TRUE only).", "Form groups; apply HAVING.", "Compute SELECT and aggregates, skipping NULLs except in COUNT(*)."], prompt: { q: "Does COUNT(dept) count a row whose dept is NULL?", a: "No. COUNT(*) does." } },
    { type: "figure", id: "sql-emp", caption: "Emp with two NULLs.", alt: "Ira CS 70, Jai CS 50, Kim EC 60, Lea EC NULL, Max NULL 40.", fig: { kind: "matrix", title: "Emp", cols: ["dept", "salary"], rows: [{ label: "Ira", cells: ["CS", 70] }, { label: "Jai", cells: ["CS", 50] }, { label: "Kim", cells: ["EC", 60] }, { label: "Lea", cells: ["EC", "NULL"], hl: true }, { label: "Max", cells: ["NULL", 40], hl: true }] } },
    { type: "example", id: "sx1", level: "gate", title: "Counting and averaging with NULLs", given: "The Emp table.", find: "COUNT(*), COUNT(salary), AVG(salary).",
      steps: [
        { say: "COUNT(*) = 5 rows; COUNT(salary) = 4 (Lea's is NULL)." },
        { say: "AVG = (70 + 50 + 60 + 40) / 4.", result: "55" },
      ],
      answer: "5, 4 and 55.",
      check: "SUM(salary)/COUNT(*) = 220/5 = 44 is a different, wrong 'average'." },
    { type: "figure", id: "sql-group", for: "sx2", caption: "Groups by dept, including the NULL group.", alt: "CS 2 rows, EC 2 rows, NULL 1 row.", fig: { kind: "matrix", title: "GROUP BY dept", cols: ["rows", "SUM(salary)", "kept by HAVING COUNT(*) ≥ 2"], rows: [{ label: "CS", cells: [2, 120, "yes"] }, { label: "EC", cells: [2, 60, "yes"] }, { label: "NULL", cells: [1, 40, "no"] }] } },
    { type: "example", id: "sx2", level: "gate", title: "GROUP BY with HAVING", given: "SELECT dept, SUM(salary) FROM Emp GROUP BY dept HAVING COUNT(*) >= 2;", find: "The result.",
      steps: [
        { say: "Groups: CS (Ira, Jai), EC (Kim, Lea), NULL (Max)." },
        { say: "HAVING keeps groups with ≥ 2 rows; EC's sum skips Lea's NULL.", result: "CS 120, EC 60" },
      ],
      answer: "(CS, 120) and (EC, 60).",
      check: "Without HAVING there would be a third row (NULL, 40)." },
    { type: "example", id: "sx3", level: "edge", title: "= NULL never matches", given: "SELECT name FROM Emp WHERE salary > 55 OR dept = NULL;", find: "The result.",
      steps: [
        { say: "salary > 55: Ira, Kim TRUE; Lea UNKNOWN." },
        { say: "dept = NULL is UNKNOWN for every row; TRUE OR UNKNOWN = TRUE, others UNKNOWN or FALSE.", result: "Ira, Kim" },
      ],
      answer: "Ira and Kim only; Max (dept NULL) is not found.",
      check: "WHERE dept IS NULL would find Max." },
    { type: "lab", lab: "sql" },
    { type: "faded", title: "Your turn", given: "SELECT COUNT(DISTINCT dept) FROM Emp;",
      steps: [{ say: "Result?", blank: true, answer: "2 (CS and EC; NULL is not counted)." }] },
    { type: "trap", wrong: "AVG(col) = SUM(col) / COUNT(*).", tempting: "Average over all rows.", whyWrong: "AVG divides by the number of non-NULL values.", rule: "AVG = SUM/COUNT(col)." },
    { type: "trap", wrong: "WHERE col = NULL finds missing values.", tempting: "It reads naturally.", whyWrong: "Comparisons with NULL are UNKNOWN, which WHERE discards.", rule: "Use IS NULL." },
    { type: "gate", text: "GATE gives small tables and asks the output of a query: watch NULLs in aggregates, HAVING versus WHERE, duplicates without DISTINCT, and join row counts." },
    { type: "recall", cards: [{ q: "COUNT(*) vs COUNT(col)", a: "Rows vs non-NULL values" }, { q: "NULL = NULL", a: "UNKNOWN" }, { q: "Aggregates in WHERE?", a: "No; use HAVING" }] },
    { type: "check", questions: [
      { id: "sq1", kind: "NAT", marks: 1, q: "Emp table: COUNT(salary)?", answer: "4", solution: "Lea's is NULL." },
      { id: "sq2", kind: "NAT", marks: 2, q: "Emp table: AVG(salary)?", answer: "55", solution: "220/4." },
      { id: "sq3", kind: "NAT", marks: 2, q: "Emp table: number of rows from SELECT dept, SUM(salary) FROM Emp GROUP BY dept HAVING COUNT(*) >= 2?", answer: "2", solution: "CS and EC." },
      { id: "sq4", kind: "MCQ", marks: 1, q: "TRUE OR UNKNOWN is", options: ["TRUE", "FALSE", "UNKNOWN", "NULL"], answer: "A", solution: "TRUE dominates OR." },
      { id: "sq5", kind: "MSQ", marks: 2, q: "Which are true?", options: ["WHERE runs before GROUP BY", "HAVING can use aggregates", "COUNT(*) skips NULL rows", "NULLs in a grouping column form one group"], answer: "A, B, D", solution: "COUNT(*) counts all rows." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "SQL", href: DB }, { label: "Topic 2: nested queries", sub: "ALL, ANY, EXISTS", href: "/study/sql" }, { label: "Relational algebra", sub: "What SQL compiles to", href: "/study/relational-algebra" }] },
    { type: "links", prereq: ["Relational algebra"], usedIn: ["Every database application"], cross: ["Discrete Mathematics: three-valued logic"] },
  ],
};

const sqlNested: Topic = {
  id: "cs.db.sql.nested",
  title: "Nested queries, EXISTS and outer joins",
  blocks: [
    { type: "hook", text: "SELECT name FROM Emp WHERE salary NOT IN (subquery) can return nothing at all, just because the subquery contains one NULL. Nested queries are powerful and full of such traps." },
    { type: "objectives", items: ["Use IN, ALL, ANY and EXISTS with subqueries.", "Explain correlated subqueries.", "Count rows from outer joins."] },
    { type: "intuition", paras: ["A subquery in WHERE produces a value or a set. IN tests membership; > ALL means greater than every value; > ANY means greater than at least one.", "A correlated subquery refers to the outer row, so it is re-evaluated for each outer row; EXISTS is true when it returns at least one row.", "x NOT IN (a, b, NULL) means x ≠ a AND x ≠ b AND x ≠ NULL; the last part is UNKNOWN, so the whole test is never TRUE."], analogyLimit: "Like asking 'is anyone in this list taller than me?' for each person in turn; the inner list can change with the person." },
    { type: "definition", name: "Subquery operators", text: "With a subquery Q:", items: ["x IN Q: x equals some value of Q. x NOT IN Q: x differs from all (UNKNOWN if Q has a NULL and no match).", "x > ALL Q: x exceeds every value (TRUE if Q is empty). x > ANY Q: x exceeds at least one (FALSE if Q is empty).", "EXISTS Q: Q returns at least one row; NOT EXISTS for 'no such row'.", "Outer joins: unmatched rows are kept with NULLs; LEFT JOIN row count ≥ left table's count."] },
    { type: "deep", sections: [
      { h: "Correlated vs uncorrelated", paras: ["An uncorrelated subquery runs once (SELECT AVG(salary) FROM Emp). A correlated one mentions the outer table (WHERE E.sid = S.sid) and logically runs once per outer row; optimisers often turn it into a join."] },
      { h: "ALL and ANY edge cases", points: ["> ALL of an empty set is TRUE (no counterexample).", "> ANY of an empty set is FALSE (no witness).", "= ANY is the same as IN; <> ALL is the same as NOT IN."], paras: [] },
      { h: "'Every' with NOT EXISTS", paras: ["Students taking every CS course: no CS course exists that the student does not take. SELECT s FROM Student WHERE NOT EXISTS (SELECT * FROM Course c WHERE c.dept='CS' AND NOT EXISTS (SELECT * FROM Enrolled e WHERE e.sid = s.sid AND e.cid = c.cid)). This double negation is SQL's division."] },
      { h: "Outer join counts", paras: ["Course LEFT JOIN Enrolled gives one row per enrolment, plus one row (with NULLs) for each course with no enrolment. With DB 3, OS 2 and VLSI 1 enrolments, the result has 6 rows."] },
    ] },
    { type: "walkthrough", steps: ["Evaluate the subquery (for correlated ones, per outer row).", "Apply IN / ALL / ANY / EXISTS with three-valued logic.", "Keep rows where the test is TRUE.", "For outer joins: matched pairs + one row per unmatched row."], prompt: { q: "What does x > ALL (empty set) give?", a: "TRUE." } },
    { type: "figure", id: "sqln-cmp", caption: "Comparisons against the CS salaries {70, 50}.", alt: "Greater than ALL means above 70; greater than ANY means above 50.", fig: { kind: "matrix", title: "salary vs CS salaries", cols: ["> ALL", "> ANY"], rows: [{ label: "Ira 70", cells: ["no", "yes"] }, { label: "Kim 60", cells: ["no", "yes"], hl: true }, { label: "Max 40", cells: ["no", "no"] }] } },
    { type: "example", id: "nx1", level: "gate", title: "ALL and ANY", given: "Emp table. EC salaries (non-NULL): {60}. CS salaries: {70, 50}.", find: "Names with salary > ALL EC salaries, and with salary > ANY CS salary.",
      steps: [
        { say: "> ALL {60}: only Ira (70).", result: "Ira" },
        { say: "> ANY {70, 50}: above 50: Ira, Kim.", result: "Ira, Kim" },
      ],
      answer: "> ALL: Ira. > ANY: Ira and Kim.",
      check: "Jai (50) is not > ANY: 50 > 50 is false." },
    { type: "figure", id: "notin", for: "nx2", caption: "One NULL in the list makes NOT IN UNKNOWN for everyone.", alt: "EC salaries {60, NULL}; every NOT IN test is unknown or false.", fig: { kind: "strip", items: [{ label: "Subquery", sub: "{60, NULL}", state: "bad" }, { label: "x ≠ 60 AND x ≠ NULL", sub: "… AND UNKNOWN", state: "done" }, { label: "Result", sub: "0 rows", state: "now" }] } },
    { type: "example", id: "nx2", level: "gate", title: "NOT IN with a NULL", given: "SELECT name FROM Emp WHERE salary NOT IN (SELECT salary FROM Emp WHERE dept = 'EC');", find: "The result.",
      steps: [
        { say: "Subquery: {60, NULL} (Lea's salary is NULL)." },
        { say: "For any x: x ≠ 60 AND x ≠ NULL = (TRUE or FALSE) AND UNKNOWN, never TRUE.", result: "0 rows" },
      ],
      answer: "Empty result.",
      check: "NOT EXISTS, or adding 'WHERE salary IS NOT NULL' to the subquery, avoids the trap." },
    { type: "example", id: "nx3", level: "edge", title: "Counting an outer join", given: "Course LEFT JOIN Enrolled ON C.cid = E.cid, with DB 3, OS 2, VLSI 1 enrolments.", find: "Rows in the result.",
      steps: [
        { say: "Matched: 3 + 2 + 1 = 6 rows; no course is unmatched." },
        { say: "Total.", result: "6" },
      ],
      answer: "6 rows. A course with no enrolments would add 1 row with NULLs.",
      check: "An inner join would also give 6 here." },
    { type: "lab", lab: "sql-nested" },
    { type: "faded", title: "Your turn", given: "SELECT name FROM Emp WHERE salary > ALL (SELECT salary FROM Emp WHERE dept = 'ME');",
      steps: [{ say: "No ME employees. Result?", blank: true, answer: "> ALL of an empty set is TRUE for every row, even Lea's NULL salary: all 5 employees." }] },
    { type: "trap", wrong: "NOT IN and NOT EXISTS always agree.", tempting: "Both mean 'not in the set'.", whyWrong: "With a NULL in the subquery, NOT IN returns nothing while NOT EXISTS behaves sensibly.", rule: "Prefer NOT EXISTS when NULLs are possible." },
    { type: "trap", wrong: "> ALL of an empty set is FALSE.", tempting: "Nothing to compare with.", whyWrong: "ALL is a universal statement; with no elements it is vacuously true.", rule: "ALL(empty) = TRUE, ANY(empty) = FALSE." },
    { type: "gate", text: "GATE asks outputs of nested queries with ALL/ANY/NOT IN on small tables (often with NULLs), correlated subqueries, and outer-join row counts." },
    { type: "recall", cards: [{ q: "NOT IN with a NULL", a: "No rows" }, { q: "> ALL (empty)", a: "TRUE" }, { q: "= ANY equals", a: "IN" }] },
    { type: "check", questions: [
      { id: "nq1", kind: "NAT", marks: 2, q: "Emp table: rows from WHERE salary NOT IN (SELECT salary FROM Emp WHERE dept = 'EC')?", answer: "0", solution: "The subquery contains NULL." },
      { id: "nq2", kind: "NAT", marks: 1, q: "Emp table: rows with salary > ANY (CS salaries {70, 50})?", answer: "2", solution: "Ira, Kim." },
      { id: "nq3", kind: "NAT", marks: 2, q: "Course LEFT JOIN Enrolled with DB 3, OS 2, VLSI 1 enrolments: rows?", answer: "6", solution: "All matched." },
      { id: "nq4", kind: "MCQ", marks: 1, q: "x > ANY (empty set) is", options: ["TRUE", "FALSE", "UNKNOWN", "an error"], answer: "B", solution: "No witness." },
      { id: "nq5", kind: "MSQ", marks: 2, q: "Which are true?", options: ["A correlated subquery refers to the outer query", "EXISTS is true if the subquery returns any row", "= ANY is equivalent to IN", "LEFT JOIN may return fewer rows than the left table"], answer: "A, B, C", solution: "LEFT JOIN keeps every left row." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Databases", sub: "Nested SQL", href: DB }, { label: "Topic 1: SQL basics", sub: "NULL and aggregates", href: "/study/sql" }, { label: "Tuple calculus", sub: "EXISTS as ∃", href: "/study/relational-algebra" }] },
    { type: "links", prereq: ["SQL basics"], usedIn: ["Complex reports"], cross: ["Tuple calculus"] },
  ],
};

